"""Original diabetes complication/therapy chapter: patient-specific drug selection."""
from qbank_authoring import question,ref,finalize
PH=ref('ADA Standards—2026: Pharmacologic Approaches','https://doi.org/10.2337/dc26-s009')
CK=ref('ADA Standards—2026: CKD and Risk Management','https://doi.org/10.2337/dc26-s011')
CV=ref('ADA/EASD: Management of Type 2 Diabetes, 2026 Consensus','https://link.springer.com/article/10.1007/s00125-026-06855-7')
EF=ref('ADA Standards—2026: Retinopathy, Neuropathy and Foot Care','https://doi.org/10.2337/dc26-S012')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An adult with type 2 diabetes and established coronary disease has A1C 6.8% on metformin. What is the best medication-selection principle?', 'Consider an agent with proven cardiovascular benefit even though A1C is near the usual goal',[
 ('Cardiovascular benefit is irrelevant once A1C is below 7%','Organ protection can be independent of additional glucose lowering.'),('A sulfonylurea is mandatory before any cardioprotective agent','That sequence is not required.'),('Stop cardiovascular risk treatment because glycemia is controlled','Residual risk remains substantial.')],
 'Glucose control and organ protection are overlapping goals', '**Selected GLP-1 receptor agonists and SGLT2 inhibitors have outcome benefits beyond their A1C effect.**',['Choose evidence for the actual ASCVD, HF and kidney phenotype.','Weight, adverse effects, access and preference matter.'], '**Use a comprehensive cardiovascular plan.**',['Address lipids, blood pressure and tobacco exposure.','Avoid promising identical outcome benefit for every member of a drug class.'],[['A1C','Not the only treatment determinant'],['ASCVD','Use an outcome-proven agent'],['Care','Integrated risk reduction']],[PH,CV],'clinical_scenario')
q('A patient with type 2 diabetes, HFrEF and eGFR 48 needs an additional drug with heart-failure outcome benefit. Which choice is most directly appropriate?', 'An SGLT2 inhibitor with proven heart-failure benefit',[
 ('Pioglitazone','Fluid retention can worsen heart failure.'),('A sulfonylurea chosen specifically for a proven HF mortality benefit','This is not a class-established HF outcome therapy.'),('A DPP-4 inhibitor assumed to have identical HF benefit','It does not provide the same established HF protection.')],
 'Choose therapy for the heart-failure phenotype', '**Dapagliflozin and empagliflozin are examples with demonstrated HF benefit.**',['Benefits are not limited to glucose lowering.','Volume status and concurrent diuretics require review.'], '**Teach sick-day and ketoacidosis precautions.**',['Check kidney function and eligibility.','Do not use a glucose-only hierarchy that overlooks the HF indication.'],[['HF benefit','Outcome-proven SGLT2 inhibitor'],['Pioglitazone','Fluid-retention concern'],['Monitoring','Volume, renal status and safety']],[PH,CV],'clinical_scenario')
q('An adult with type 2 diabetes has eGFR 28 and albuminuric CKD. Why can an SGLT2 inhibitor still be useful despite reduced glycemic efficacy?', 'Kidney and cardiovascular protection can persist when urinary glucose-lowering efficacy is diminished',[
 ('The A1C effect becomes stronger as filtration falls','Glucose-lowering efficacy generally declines.'),('The drug has no role below eGFR 45 in all indications','Outcome-based use extends to lower eligible eGFR.'),('A reduced glucose effect means no biological benefit is possible','Hemodynamic and other protective effects are not identical to glucose excretion.')],
 'Separate the glucose indication from the organ-protection indication', '**ADA recommends initiation for eligible CKD patients at eGFR at least 20 mL/min/1.73 m².**',['Individual product labels and clinical factors still apply.','Other therapy may be needed for glycemic control.'], '**Assess volume and acute illness risk.**',['An early modest eGFR dip can be expected.','Do not mislabel every initial dip as progressive nephrotoxicity.'],[['Lower GFR','Less glycemic effect'],['Outcome benefit','Can remain important'],['Initiation threshold','Eligible patients at least 20']],[CK,PH],'clinical_scenario')
q('A patient with type 2 diabetes, obesity and prior ischemic stroke seeks additional glucose and weight treatment. Which class offers a relevant proven ASCVD option?', 'A GLP-1 receptor agonist with demonstrated cardiovascular benefit',[
 ('Any DPP-4 inhibitor as a proven equivalent weight-loss and MACE therapy','DPP-4 agents do not provide the same magnitude of weight loss or established MACE reduction.'),('Pioglitazone because it always produces weight loss','It commonly causes weight gain and fluid retention.'),('Insulin chosen solely because it guarantees weight loss','Insulin can promote weight gain and is selected for other indications.')],
 'Match the treatment to both metabolic and vascular priorities', '**Selected GLP-1 therapies improve weight and cardiovascular outcomes.**',['Benefits and licensing differ by agent.','Gastrointestinal tolerance and contraindications require review.'], '**Use shared selection rather than a class-wide assumption.**',['Continue vascular prevention.','Monitor glycemia as concurrent insulin or secretagogues may need adjustment.'],[['Priority','Weight plus ASCVD'],['Suitable evidence','Selected GLP-1 agents'],['Safety','Tolerability and concurrent hypoglycemia risk']],[PH,CV],'clinical_scenario')
q('An adult labeled type 2 has weight loss, polyuria, glucose 380 mg/dL and A1C 12.5%. What is the best initial therapeutic principle?', 'Consider prompt insulin and evaluate insulin deficiency and ketosis',[
 ('Delay all treatment until three noninsulin classes have failed','Catabolic symptomatic severe hyperglycemia calls for timely treatment.'),('A near-term lifestyle review alone is sufficient regardless of symptoms','This leaves clinically important metabolic risk untreated.'),('A GLP-1 drug must always precede insulin even in this presentation','The recommendation favoring GLP-1 before insulin has severe-hyperglycemia exceptions.')],
 'Catabolism changes the usual treatment sequence', '**ADA recommends considering insulin with symptoms or very high A1C or glucose.**',['Examples include A1C above 10% or glucose at least 300 mg/dL.','Autoimmune diabetes and other insulin-deficient forms may have been misclassified.'], '**Stabilize before refining the long-term regimen.**',['Check ketones and acute illness as indicated.','Insulin can sometimes be simplified after glucotoxicity resolves if secretion is adequate.'],[['Symptoms','Catabolism/polyuria'],['Severity','Very high glucose/A1C'],['Action','Prompt insulin consideration and classification review']],[PH],'clinical_scenario')
q('Type 2 diabetes remains above goal without severe hyperglycemia, ketosis or catabolism. Which injectable strategy is generally preferred before insulin when suitable?', 'GLP-1-based therapy',[
 ('Insulin must always be the first injectable regardless of phenotype','GLP-1-based therapy is generally preferred in this nonsevere context.'),('Insulin is permanently contraindicated once a GLP-1 drug is used','Insulin can be added when needed.'),('A prandial-only insulin regimen with no consideration of weight or risk','That is not the usual preferred first injectable strategy here.')],
 'The preference applies within a defined clinical context', '**GLP-1-based therapy can provide strong glucose lowering with weight benefit and less intrinsic hypoglycemia.**',['Cost, tolerance and contraindications affect choice.','Severe insulin deficiency is a different situation.'], '**Avoid therapeutic inertia if the selected strategy is insufficient.**',['Reassess goals and adherence barriers.','Combine with basal insulin when appropriate rather than treating the sequence as a prohibition.'],[['Nonsevere type 2','Often GLP-1-based first'],['Severe/catabolic','Consider insulin promptly'],['Follow-up','Escalate according to response']],[PH])
q('Which action best describes the major glucose-lowering effect of metformin?', 'Reduction of hepatic glucose production with improvement in insulin sensitivity',[
 ('Direct stimulation of insulin release through beta-cell KATP closure','That describes sulfonylureas.'),('Blockade of proximal glucose reabsorption','That describes SGLT2 inhibition.'),('Inhibition of intestinal alpha-glucosidase as its principal action','That describes acarbose.')],
 'Mechanism helps predict benefits and limitations', '**Metformin does not directly force insulin secretion.**',['Its intrinsic hypoglycemia risk is low.','Gastrointestinal effects and B12 depletion can be important.'], '**Use within renal and acute-illness safety limits.**',['Hypoxia, severe sepsis and acute renal deterioration can require temporary withholding.','A useful baseline glucose drug does not replace indicated cardiorenal therapy.'],[['Metformin','Hepatic glucose production'],['Sulfonylurea','Insulin secretion'],['SGLT2 inhibitor','Renal glucose handling']],[PH])
q('A patient on metformin develops persistent eGFR 24 mL/min/1.73 m². Which action is appropriate?', 'Discontinue metformin because eGFR is below 30 and choose a suitable alternative',[
 ('Continue the maximum dose without review','This exceeds the usual renal safety boundary.'),('Increase the dose to overcome reduced filtration','This can increase accumulation risk.'),('A1C at goal removes the renal contraindication','Glycemic control does not remove drug-safety concerns.')],
 'Renal eligibility differs among glucose-lowering medicines', '**Metformin is contraindicated when eGFR is below 30.**',['Dose and continuation decisions at higher reduced eGFR require review.','Acute illness can create a temporary contraindication even before chronic thresholds are crossed.'], '**Choose alternatives according to glucose and organ needs.**',['Avoid abrupt loss of all glycemic treatment.','Reassess renal trajectory and contributing illness.'],[['eGFR below 30','Stop metformin'],['Acute deterioration','Reassess promptly'],['Replacement','Individualized safer regimen']],[PH,CK],'clinical_scenario')
q('A patient with severe symptomatic gastroparesis is being considered for a GLP-1 receptor agonist. Which issue is most relevant?', 'Further slowing of gastric emptying can worsen symptoms and affect suitability',[
 ('These agents reliably accelerate gastric emptying','Their effect is generally in the opposite direction.'),('All gastrointestinal symptoms prove pancreatitis','Common and serious causes require different assessment.'),('Gastroparesis has no bearing on choice or tolerability','It is clinically relevant.')],
 'A useful metabolic action can be undesirable in a particular phenotype', '**GLP-1 therapies can cause nausea, vomiting and delayed gastric emptying.**',['Severity and the specific product label guide selection.','Hydration and nutrition can be compromised by persistent symptoms.'], '**Review alternatives and investigate red flags.**',['Slow titration can improve ordinary intolerance but does not solve every severe condition.','Persistent severe abdominal pain needs assessment rather than routine reassurance.'],[['Potential benefit','Satiety and weight reduction'],['Potential problem','Delayed gastric emptying'],['Selection','Symptoms and label-specific precautions']],[PH],'clinical_scenario')
q('Why are SGLT2 inhibitors generally withheld before elective surgery and during prolonged fasting or serious acute illness?', 'To reduce ketoacidosis risk in a setting of reduced intake and relative insulin deficiency',[
 ('They must be continued because normal glucose excludes DKA','Euglycemic DKA can occur.'),('A single skipped meal always requires permanent discontinuation','Temporary safety planning is different from permanent cessation.'),('Their only perioperative issue is isolated cholesterol elevation','Ketoacidosis and volume issues are more immediate concerns.')],
 'Glucose alone may not warn of the complication', '**ADA commonly advises holding these drugs three to four days before scheduled surgery, depending on the agent.**',['Restart only after clinical stability and adequate intake according to the plan.','Urgent procedures require heightened ketone and metabolic vigilance.'], '**Maintain necessary insulin in insulin-deficient patients.**',['Provide written sick-day instructions.','Check the specific drug and local protocol rather than guessing the interval.'],[['Risk setting','Surgery/fasting/acute illness'],['Hazard','Potential euglycemic DKA'],['Plan','Agent-specific hold and safe restart']],[PH])
q('Which adverse effect is particularly associated with SGLT2-related glycosuria?', 'Genital mycotic infection',[
 ('A guaranteed severe bacterial kidney infection in every patient','The established common association is genital mycosis; severe infection risk requires balanced assessment.'),('Obligatory severe hypoglycemia when used alone','Intrinsic hypoglycemia risk is low.'),('Universal permanent renal failure from the initial eGFR dip','An expected early hemodynamic dip is not the same as progressive renal injury.')],
 'Discuss common manageable harms alongside outcome benefits', '**Glycosuria changes the local environment and increases genital fungal infection risk.**',['Volume depletion and rare ketoacidosis are other safety considerations.','Symptoms suggestive of serious infection need prompt assessment.'], '**Use prevention advice and individualized treatment.**',['Review recurrent severe intolerance when deciding continuation.','Do not overstate every possible complication as inevitable.'],[['Common association','Genital fungal infection'],['Other risks','Volume depletion and ketoacidosis'],['Care','Education and symptom-based review']],[PH])
q('A patient receiving sitagliptin is starting a GLP-1 receptor agonist. Which regimen change is generally appropriate?', 'Stop the DPP-4 inhibitor rather than routinely combining the two',[
 ('Continue both because their glucose effects are strongly additive','ADA does not recommend the combination because it lacks meaningful additional lowering.'),('Stop all other cardiorenal therapy automatically','Each drug needs an indication-specific review.'),('Never use GLP-1 therapy if a DPP-4 inhibitor was previously prescribed','Prior DPP-4 exposure is not a permanent exclusion.')],
 'Overlapping incretin mechanisms can add cost without useful benefit', '**DPP-4 inhibition enhances endogenous incretin activity while GLP-1 therapy directly activates the pathway.**',['The same caution applies to dual GIP/GLP-1 therapy.','Other combinations may be appropriate when mechanisms and benefits complement.'], '**Reconcile the full list when adding treatment.**',['Review insulin and sulfonylurea doses for hypoglycemia risk.','Reduce unnecessary regimen complexity.'],[['Combination','DPP-4 plus GLP-1-based'],['Recommendation','Not routinely recommended'],['Reason','Little additional glucose benefit']],[PH],'clinical_scenario')
q('A person with type 2 diabetes and symptomatic heart failure is taking pioglitazone. Which drug effect warrants review?', 'Sodium retention and edema that can exacerbate heart failure',[
 ('A reliably strong loop-like diuretic effect','Pioglitazone can retain rather than remove fluid.'),('A direct anti-ketogenic replacement for insulin in type 1 disease','It does not replace insulin.'),('No influence on body weight or fluid status','Weight gain and edema are relevant adverse effects.')],
 'Insulin sensitization has important trade-offs', '**Thiazolidinediones activate PPAR-gamma and can cause fluid retention.**',['Fracture risk and weight gain also influence selection.','Potential benefits in other metabolic contexts do not remove HF precautions.'], '**Reassess the regimen rather than treating edema in isolation.**',['Choose appropriate HF-beneficial therapy where eligible.','Consider the patient’s congestion, cardiac status and alternatives.'],[['Mechanism','PPAR-gamma activation'],['Concern','Fluid retention'],['HF context','Often unsuitable']],[PH,CV],'clinical_scenario')
q('Which oral diabetes drug is particularly unsuitable in a frail patient with advanced CKD because active metabolites can prolong hypoglycemia?', 'Glibenclamide (glyburide)',[
 ('Linagliptin solely because it has active renally cleared sulfonylurea metabolites','It is not a sulfonylurea and has different clearance.'),('Acarbose because it directly drives prolonged insulin release','Its principal action is intestinal carbohydrate digestion inhibition.'),('An SGLT2 inhibitor because every dose produces prolonged hypoglycemia alone','That is not its characteristic intrinsic effect.')],
 'Class and metabolite handling affect duration of harm', '**Long-acting sulfonylureas can cause prolonged severe hypoglycemia, especially with reduced clearance.**',['Food irregularity and frailty amplify risk.','Even shorter-acting choices need caution.'], '**Prefer a lower-risk individualized regimen.**',['Review renal dosing and treatment goals.','After an event, monitor for recurrence rather than discharge from one normal value.'],[['Drug','Glyburide/glibenclamide'],['Risk amplifier','CKD and frailty'],['Harm','Prolonged hypoglycemia']],[PH],'clinical_scenario')
q('A patient taking acarbose and insulin develops mild hypoglycemia. Which oral rescue is preferred?', 'Glucose rather than sucrose',[
 ('Sucrose is always equally rapid despite alpha-glucosidase inhibition','Its digestion can be delayed.'),('Additional acarbose','This does not treat the low.'),('A high-fat meal as the fastest rescue','Fat delays rapid carbohydrate delivery.')],
 'The drug’s digestive mechanism changes rescue choice', '**Acarbose delays intestinal breakdown of complex carbohydrates and disaccharides.**',['Glucose does not require that breakdown.','Acarbose alone rarely causes hypoglycemia, but insulin can.'], '**Treat promptly and reassess.**',['Follow the standard repeat-glucose check plan.','Review the insulin-food match and risk of recurrence.'],[['Drug action','Alpha-glucosidase inhibition'],['Preferred rescue','Glucose'],['Combined therapy','Insulin can cause lows']],[PH])
q('Which receptor combination is targeted by tirzepatide?', 'GIP and GLP-1 receptors',[
 ('DPP-4 and SGLT2 transporters','These are different targets.'),('Insulin and mineralocorticoid receptors','That is not tirzepatide’s mechanism.'),('Glucagon and somatostatin receptors as its licensed dual target','This is a different receptor combination.')],
 'Dual incretin activity is not the same as combining any two diabetes drugs', '**Tirzepatide is a dual GIP/GLP-1 receptor agonist.**',['It can produce substantial glucose and weight effects.','GI tolerance, contraindications and concurrent hypoglycemia-causing drugs matter.'], '**Use agent-specific outcome and safety evidence.**',['Do not assume every GLP-1 trial result automatically applies identically.','Titrate according to the approved regimen and patient response.'],[['GIP','Glucose-dependent insulinotropic polypeptide'],['GLP-1','Glucagon-like peptide-1'],['Selection','Specific evidence and patient factors']],[PH])
q('Basal insulin escalation has normalized fasting glucose, but A1C remains high and CGM shows large postmeal excursions with overnight lows. What is the best next principle?', 'Stop reflex basal escalation and address meal-related hyperglycemia with an appropriate additional strategy',[
 ('Continue increasing basal until every postmeal value is normal','This can worsen overnight hypoglycemia.'),('Ignore postmeal excursions because fasting glucose is controlled','Overall exposure and variability remain important.'),('All elevated A1C must reflect an invalid assay','The documented postmeal pattern explains a plausible cause.')],
 'Overbasalization treats the wrong component', '**Basal insulin mainly targets fasting hepatic glucose output.**',['GLP-1-based therapy or meal insulin may address residual excursions.','Meal content, timing and technique also require review.'], '**Use the pattern to select treatment.**',['Reduce hypoglycemia risk while revising the regimen.','Do not use a single dose cutoff as a substitute for the observed pattern.'],[['Fasting','At goal'],['After meals','High'],['Overnight','Low signals excess basal effect']],[PH],'clinical_scenario')
q('A person with unpredictable meal timing asks about switching from basal-bolus insulin to twice-daily premixed insulin. What is the main trade-off?', 'Premixed regimens may simplify injections but reduce flexibility and require more consistent meals',[
 ('Premixed insulin independently adjusts basal and meal components with every dose','The fixed ratio limits independent adjustment.'),('Premixed insulin eliminates hypoglycemia risk','It can cause hypoglycemia, particularly with missed meals.'),('Basal-bolus always requires identical carbohydrate at every meal','It can allow more flexibility when used with education.')],
 'Convenience and flexibility are different treatment attributes', '**A fixed mixture couples intermediate/basal-like and prandial components.**',['Meal regularity and self-management capacity affect suitability.','Cost and access can influence the choice.'], '**Choose a workable regimen with the patient.**',['Teach how to respond to delayed meals and illness.','Monitor patterns after any switch rather than copying doses mechanically.'],[['Premix advantage','Fewer injections for some'],['Limitation','Fixed component ratio'],['Key need','Predictable intake and safety plan']],[PH],'clinical_scenario')
q('A person with type 2 diabetes plans pregnancy while taking an SGLT2 inhibitor. Which approach is appropriate?', 'Arrange preconception medication review and transition to a pregnancy-appropriate regimen, commonly insulin when needed',[
 ('Continue every noninsulin drug because A1C is acceptable','Glycemic control does not establish fetal medication safety.'),('Stop all treatment and allow hyperglycemia','Hyperglycemia also carries maternal and fetal harm.'),('Use the nonpregnant drug algorithm without adjustment','Pregnancy changes goals and treatment eligibility.')],
 'Plan the regimen before conception rather than after exposure', '**SGLT2 inhibitors are not routine pregnancy therapies.**',['Insulin is the preferred treatment for type 2 diabetes in pregnancy in ADA guidance.','Other drugs and cardiovascular medicines also need review.'], '**Coordinate glucose optimization and reproductive counseling.**',['Assess complications before pregnancy when feasible.','Avoid abrupt unplanned treatment gaps.'],[['Before conception','Medication and complication review'],['Glycemia','Optimize safely'],['Regimen','Pregnancy-appropriate therapy']],[PH])
q('A patient taking saxagliptin develops worsening heart failure. Which evidence-based concern merits review?', 'A heart-failure hospitalization signal associated with saxagliptin',[
 ('All DPP-4 inhibitors have proven identical HF mortality benefit','They are not interchangeable HF outcome treatments.'),('Saxagliptin is a loop diuretic expected to relieve congestion','It is a DPP-4 inhibitor.'),('The drug must be the only possible cause of all dyspnea','Other causes and the whole cardiac status still require assessment.')],
 'Within-class outcome differences can matter', '**Saxagliptin has a recognized HF hospitalization concern.**',['Renal function and comorbidity affect selection and dosing.','Do not generalize that every DPP-4 agent has the same signal or the same benefit.'], '**Reassess treatment in the HF context.**',['Use an outcome-proven HF strategy where appropriate.','Investigate congestion and other precipitating factors.'],[['Class','DPP-4 inhibitor'],['Specific concern','Saxagliptin HF hospitalization'],['Action','Cardiac and medication review']],[PH,CV],'clinical_scenario')
